const CACHE='ping-learning-v8';
const FILES=[...Array.from({length:9},(_,i)=>`/assets/exercise-${i+1}.webp`),'/','/index.html','/style.css','/story.js','/translations.js','/core.js','/app.js','/books.js','/experience.js','/collections.js',...Array.from({length:3},(_,i)=>`/assets/colors-${i+1}.webp`),'/assets/original-readthrough.mp3',...Array.from({length:8},(_,i)=>`/assets/garden-${i+1}.webp`),'/manifest.webmanifest','/assets/panda.svg',...Array.from({length:8},(_,i)=>`/assets/page-${i+1}.webp`)];
self.addEventListener('install',event=>event.waitUntil(self.skipWaiting()));
self.addEventListener('activate',event=>event.waitUntil(self.clients.claim()));
self.addEventListener('message',event=>{if(event.data?.type==='CACHE_APP')event.waitUntil((async()=>{try{const cache=await caches.open(CACHE);const fetched=await Promise.all(FILES.map(async url=>{const res=await fetch(url,{cache:'reload'});if(!res.ok||res.redirected)throw Error('download');if(url.endsWith('.js')&&!/javascript/.test(res.headers.get('content-type')||''))throw Error('type');return [url,res]}));for(const [url,res]of fetched)await cache.put(url,res);event.ports[0]?.postMessage({ok:true})}catch{event.ports[0]?.postMessage({ok:false})}})())});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).catch(async()=>{const cache=await caches.open(CACHE);const cached=await cache.match(event.request,{ignoreSearch:true});return cached||(event.request.mode==='navigate'?await cache.match('/'):null)||Response.error()}))});
